objective(14, 'incident-team', '사고 분류와 CERT의 예방·대응 역할', [1, 2, 3, 18],
  '사고가 나서 연락할 사람을 찾기 시작하면 판단이 늦어진다. 무엇을 보호하고 누가 결정·조사·조치할지 평소에 나누어 두는 이유를 이해한다.',
  ['교안은 일반·중대 분류와 악성코드 감염, 비인가 접근, 서비스 거부, 웹 해킹, 오남용의 다섯 유형을 제시한다. 현대 보충인 NIST SP 800-61 Rev.3의 사고 개념은 정당한 권한 없이 정보·시스템의 기밀성·무결성·가용성을 실제로 위태롭게 하거나 그 위험이 임박한 경우, 또는 법·보안 정책·보안 절차·허용 가능한 사용 정책의 위반이나 임박한 위반 위협도 포함한다. 이미 피해가 확정된 뒤에만 대응하는 것은 늦을 수 있다. 다만 모든 관찰 이벤트가 곧 사고인 것은 아니며 조직의 기준과 증거를 분석해 판단한다. 이는 국내 현행 법적 정의를 대신하지 않는다. 같은 사건이 여러 유형에 걸칠 수 있어 영향·중요 자산·확산 정도를 함께 확인한다.',
   'CERT는 Computer Emergency Response Team이라는 명칭으로 대응 조직의 협력 창구를 설명한다. 사고 대응뿐 아니라 자산·위험 분석, 정책 자문, 관제·비상 대응 구축, 교육훈련과 외부 공조를 맡는다. 교안의 최고책임자는 총괄·의사결정, 관리자는 계획·감독·기록 관리, 담당자는 조사·조치 실무, 기획은 전략, 관제는 상시 감시·초동 대응으로 구분한다. 실제 배분은 조직의 승인된 역할에 따르고 비상 연락 경로를 사전에 유지한다.'],
  '조직의 역할·연락망·자산 이해는 사고 전부터 준비하고 사고 영향에 맞게 대응을 조정한다.',
  [['최고책임자', '대응·재발 방지의 총괄 결정', '중요 서비스 조치 승인'], ['담당자', '사실 확인·원인 분석·실무 조치', '증거 수집과 보고'], ['관제', '상시 감시·초동 조사와 인계', '의심 경보 전파']],
  '가상 기관에서 자료 유출과 서비스 중단이 동시에 의심된다.',
  ['기밀성과 가용성 영향, 중요 자산과 확산 범위를 함께 기록한다.', '비상 연락망으로 책임자·관제·운영·조사 담당을 소집하고 역할별 조치를 연결한다.'],
  '분류명을 하나 고르는 데 머무르지 않고 영향과 책임을 연결한다.',
  'CERT는 사고가 난 뒤에만 일한다는 생각은 예방·교육·위험 분석 기능을 놓친다.',
  '웹 해킹과 정보 유출은 반드시 서로 배타적인 사건일까?', '아니다. 웹 취약점으로 침입해 자료를 유출할 수 있으므로 원인과 피해를 여러 관점에서 기록한다.', [1, 2]);
q("five-types", "concept", 1, "교안의 다섯 침해사고 유형에 해당하는 묶음은?", "악성코드 감염·비인가 접근·서비스 거부·웹 해킹·오남용", "교안의 교육용 분류를 재구성한 것이며 현행 법률의 완전한 분류라고 주장하지 않는다.", "악성코드 감염·비인가 접근·서비스 거부·웹 해킹·증거 보존", "증거 보존은 조사 절차다. 교안의 다섯 유형에서는 이 자리에 오남용이 들어간다.", "악성코드 감염·비인가 접근·서비스 거부·위기 경보·오남용", "위기 경보는 대응 강도 분류이며 교안 사고 유형의 웹 해킹을 대신하지 않는다.", "악성코드 감염·비인가 접근·사고 보고·웹 해킹·오남용", "사고 보고는 대응 활동이며 교안의 서비스 거부 유형과 구분한다.", [1,2]);
q("cert-before", "concept", 1, "CERT의 사고 전 활동에 해당하는 것은?", "자산·위험 분석과 정책·교육훈련 준비", "예방과 준비도 대응 역량을 만드는 주요 역할이다.", "발생한 사고의 피해 범위만 조사하고 준비 활동은 제외", "피해 조사는 필요하지만 사고 후 활동에 해당하고 사고 전 예방·준비를 배제한다.", "복구가 끝난 사건의 보고서만 작성", "사고 후 보고와 사고 전 자산·위험 분석·교육훈련은 다른 시점의 활동이다.", "의심 시스템을 격리하고 휘발성 자료를 수집", "이 활동은 발생·의심 사고의 대응이며 질문이 묻는 평상시 예방·준비와 구분한다.", [2,3]);
q('role-decision', 'contrast', 2, '교안의 최고책임자와 담당자 역할 비교로 적절한 것은?', '최고책임자는 총괄·감독, 담당자는 사실 확인·원인 분석·조치 실무에 중점을 둔다.', '의사결정 책임과 기술 실무를 나누면서 보고로 연결한다.', '최고책임자만 모든 로그를 직접 작성해야 한다.', '총괄 책임과 모든 수집 실무를 같은 일로 보았다.', '담당자는 어떤 결과도 보고하지 않는다.', '실무 조치와 관리자 보고의 연결이 필요하다.', '관제는 사건 전파를 하면 안 된다.', '관제의 초동 대응과 전파 역할에 반한다.', [2, 3]);
q('overlap', 'application', 2, '가상 웹 침입 뒤 자료 변조와 서비스 중단이 함께 발견됐다. 분류 방법은?', '원인과 피해를 나누어 여러 관련 유형·영향을 기록한다.', '사건은 여러 보호 성질과 유형에 걸칠 수 있어 하나만 고집하면 범위를 놓친다.', '유형이 하나여야 하므로 서비스 중단을 숨긴다.', '실제 피해를 누락하여 대응을 왜곡한다.', '웹 해킹이면 가용성은 볼 필요 없다.', '웹 침입도 서비스 운영에 영향을 줄 수 있다.', '교안 분류명만으로 피해 규모를 확정한다.', '영향·범위·중요도 증거가 추가로 필요하다.', [1, 2]);
q('contact', 'application', 2, '가상 비상 연락 체계를 사고 전에 점검하는 이유는?', '신고·소집·승인·공조의 지연과 담당 혼선을 줄이기 위해서', '긴급 상황의 기술 조치와 조직 의사결정을 신속히 연결할 수 있다.', '연락망만 있으면 모든 취약점이 사라지기 때문', '조직 준비가 기술적 원인 제거를 대신하지 않는다.', '평소에는 자산을 몰라도 되기 때문', '자산 이해가 있어야 영향과 우선순위를 판단한다.', '담당자가 책임 없이 조치하게 하기 위해서', '역할·승인·기록은 오히려 책임을 분명하게 한다.', [3]);

objective(14, 'response-stages', '예방부터 조사·보고·재발 방지까지', [3, 4],
  '서비스가 다시 열렸다는 이유로 사고를 끝내면 원인과 배운 점을 잃는다. 대응 단계마다 다른 질문과 산출물이 필요하다.',
  ['교안은 예방, 탐지, 초동 대응, 대응 전략 수립, 사고 조사, 보고서 작성, 재발 방지를 설명한다. 초동 대응은 기본 사실과 시각·자산·증상을 기록하고 신고·소집한다. 전략 단계는 영향과 필요한 조사·조치 방법을 검토하고 권한 있는 결정을 연결한다. 조사에서는 원인·경로·발생 범위·피해와 불확실성을 증거로 정리한다.',
   '현대 보충: 대응은 한 번의 일직선 절차보다 상황에 따라 탐지·조사·격리·복구가 반복되는 활동이다. 교안의 중요도·피해규모 조합은 조사 착수의 예시 정책이지 다른 사고를 무시하는 보편 기준이 아니다. 보고서는 의사결정자가 이해할 영향·확인 사실·조치·남은 위험을 담는다. 재발 방지는 정책·절차·기술 수정·교육·장기 개선을 담당자와 추적 가능한 작업으로 연결한다.'],
  '각 단계에서 무엇을 확인하고 누가 어떤 결정을 했는지 남기며 복구 후에도 개선을 추적한다.',
  [['초동 대응', '기본 사실 확인과 신고·소집', '시각·자산·증상 기록'], ['사고 조사', '증거로 원인과 범위를 분석', '침입 경로와 영향 연결'], ['재발 방지', '원인과 운영 빈틈을 개선', '패치·권한·연락 절차 변경']],
  '가상 서비스가 복구됐지만 침입 경로와 피해 문서 수가 아직 불명확하다.',
  ['복구 상태와 조사 상태를 따로 기록하고 보존된 자료로 원인·범위를 계속 확인한다.', '확인된 영향·조치·미확인 범위를 보고하고 원인 제거 작업을 추적한다.'],
  '운영 정상화만으로 조사 완료와 재발 방지 완료를 선언하지 않는다.',
  '조사 착수 표의 조건 밖이면 아무 대응도 필요 없다는 생각은 조직별 판단과 새 위협을 배제한다.',
  '보고서에 확정 사실과 가설을 나누는 이유는?', '결론의 근거와 한계를 보여 주어 조치·추가 조사·우선순위 판단을 정확히 하기 위해서다.', [1, 3]);
q('initial', 'application', 1, '가상 초동 대응에서 우선 남겨야 할 것은?', '발견 시각·대상 자산·관찰 증상과 수행한 조치', '이후 조사와 의사결정의 출발점이 되는 기본 사실이다.', '확인하지 않은 공격자 실명', '추정 신원을 사실로 쓰면 잘못된 결론을 만들 수 있다.', '원인 분석 전의 성공 발표문만', '확인과 대응에 필요한 정보가 부족하다.', '기록을 남기지 않은 설정 변경 목록', '실제 조치의 시각과 내용을 검증하기 어렵다.', [3]);
q('strategy', 'concept', 2, '대응 전략을 수립하는 이유로 적절한 것은?', '영향·증거·업무 제약을 고려해 조사·조치 방법과 책임을 결정하기 위해서', '실무 조치가 보호 목적과 승인된 판단에 맞게 연결되어야 한다.', '어떤 상황에서도 동일한 삭제를 자동 적용하기 위해서', '사건별 영향·증거·자산 조건이 다르다.', '모든 미확인 사실을 확인된 것처럼 바꾸기 위해서', '불확실성을 지우면 판단이 왜곡된다.', '복구되면 보고를 생략하기 위해서', '운영 회복과 보고·개선 책임은 별개다.', [3, 4]);
q('report', 'application', 2, '의사결정용 사고 보고서에 적절한 구성은?', '확인된 영향·근거·조치·미확인 범위·다음 작업', '결정권자가 현재 상태와 남은 위험을 이해하고 필요한 지원을 고를 수 있다.', '전문 용어만 나열하고 영향은 생략', '기술 용어만으로 사업·사용자 영향을 판단하기 어렵다.', '미확인 가설을 확정 원인으로 기록', '근거 수준을 왜곡하여 잘못된 후속 조치를 유도한다.', '조치 시각을 모두 지워 간단히 작성', '전후 관계와 책임 있는 조치의 검증을 방해한다.', [4]);
q("lessons", "application", 2, "사고 후 같은 취약점과 연락 혼선이 발견됐다. 재발 방지에 적절한 것은?", "기술 수정과 연락 절차 개선을 담당·기한·확인 방법과 연결한다.", "원인과 운영 빈틈에 대한 실행·검증 가능한 작업으로 바꿔야 재발 가능성을 줄인다.", "복구되면 기술 수정만 남기고 연락 혼선은 개선하지 않음", "연락 혼선도 대응 지연 원인이므로 절차 개선의 담당·기한·검증이 필요하다.", "기술 수정과 연락 개선을 권고하되 담당과 확인 방법은 정하지 않음", "추상적 권고만으로 실행 책임과 개선 완료 여부를 추적하기 어렵다.", "다음 사고에서 효과를 볼 때까지 개선 이행을 점검하지 않음", "사고 재발 전에 검증할 수 있도록 수정·훈련·확인 방법을 정해야 한다.", [4]);
q("investigation-policy", "evidence", 2, "교안의 조사 착수 규모 기준에 못 미치지만 관리자 자격 탈취는 확인됐고 아직 자료 유출은 확인되지 않았다. 조사 필요성을 어떻게 판단할까?", "교안 표는 예시 정책이며 위험과 추가 조사 필요성을 검토한다.", "규모가 작아도 새 경로나 확산 위험 때문에 조사가 필요할 수 있다.", "자료 유출 완료가 확인될 때까지 기록·판단을 보류한다.", "현대 사고 개념에는 임박한 위험도 포함하므로 확인된 자격 탈취를 피해 확정 전이라고 무시하면 안 된다.", "중요 자격 탈취가 있어도 소규모이면 기밀성 위험은 없다.", "자료가 아직 유출되지 않았어도 관리자 자격 노출은 임박한 위험을 만들 수 있다.", "모든 단일 경보도 증거 분석 없이 같은 확정 사고로 분류한다.", "이 사례에는 자격 탈취의 확인 근거가 있으며 모든 관찰 이벤트를 사고로 단정하는 것과 다르다.", [4]);

objective(14, 'contain-recover', '유형별 초동 조치·증거 보존·안전한 복구', [5, 6, 7, 8, 9],
  '확산을 막는 조치가 증거를 지울 수 있고 복구를 서두르면 같은 경로로 재침입할 수 있다. 보호·조사·정상화의 목적을 함께 고려한다.',
  ['교안의 악성코드·비인가 접근·DoS·웹 해킹·오남용 대응은 탐지·신고, 확산 방지, 원인·범위 분석, 원상 복구, 결과 기록의 공통 흐름을 갖는다. 악성코드는 감염 경로와 전파 범위, 비인가 접근은 계정·행위, DoS는 가용성·트래픽, 웹 해킹은 변조·서버 실행·DB, 오남용은 자료 사용·권한을 중점 확인한다. 외형적 증상 하나만으로 유형이나 원인을 확정하지 않는다.',
   '현대 보충: 먼저 위험에 맞는 격리와 증거 보존을 계획한다. 전원을 무조건 끄면 메모리·연결 등 휘발성 정보가 사라지고, 반대로 계속 켜 두면 피해가 커질 수도 있다. 가능한 네트워크 격리와 숙련된 수집, 안전·업무 영향·확산 속도를 고려해 조치를 결정하고 시각·담당·방법을 기록한다. 복구는 신뢰 가능한 백업·재설치뿐 아니라 원인 제거·자격 통제·복구 후 모니터링까지 연결한다.'],
  '확산 방지와 증거 보존을 함께 판단하고 원인을 고친 뒤 복구 상태를 확인한다.',
  [['격리', '피해 확대 경로를 제한', '필요한 네트워크 연결 차단'], ['증거 보존', '조사 가능한 상태·기록 유지', '원본과 수집 이력 보호'], ['복구', '신뢰 가능한 서비스 상태로 회복', '검증한 백업과 원인 제거']],
  '가상 서버에서 감염이 의심되고 아직 프로세스와 연결 정보가 남아 있다.',
  ['확산 위험·안전·서비스 영향을 평가하고 가능한 격리 방법을 정한다.', '숙련된 절차로 필요한 휘발성 자료와 로그를 보존하고 조치를 기록한 뒤 원인 제거와 복구를 수행한다.'],
  '항상 전원 차단 또는 항상 가동이라는 한 가지 규칙 대신 상황별 근거로 결정한다.',
  '재설치하면 조사 기록과 취약점 수정도 자동 완료된다는 생각은 증거와 재침입 원인을 놓친다.',
  '백업으로 화면이 돌아오면 같은 취약점도 제거됐을까?', '보장되지 않는다. 백업의 신뢰성과 취약점·탈취 자격·지속성 경로의 제거를 별도로 확인해야 한다.', [3]);
q('poweroff', 'application', 3, '확산 위험이 있는 가상 감염 서버에 대한 적절한 판단은?', '격리 가능성·휘발성 증거·안전과 영향을 평가해 조치를 선택하고 기록한다.', '전원 차단과 가동 유지 모두 조건별 비용이 있어 근거 있는 대응이 필요하다.', '증거 상태와 무관하게 항상 전원을 뽑는다.', '메모리·연결 증거를 잃고 업무 영향도 고려하지 못한다.', '어떤 확산이 있어도 반드시 계속 연결해 둔다.', '진행 중인 피해를 방치할 수 있다.', '분석 전 모든 로그를 덮어쓴다.', '원인·범위 확인의 증거를 훼손한다.', [6, 7, 8]);
q("malware-vs-dos", "contrast", 2, "악성코드 감염과 DoS 대응에서 중점 확인의 올바른 비교는?", "감염은 유입·전파 범위, DoS는 트래픽·가용성 영향을 중심으로 본다.", "공통 절차 안에서도 원인과 관찰할 영향에 차이가 있다.", "감염은 트래픽만, DoS는 감염 파일만 조사한다.", "주된 원인과 영향을 반대로 좁혔다. 감염 전파와 가용성 영향을 중심으로 보완해야 한다.", "DoS는 정상 서비스가 복구되면 원인·자원 분석이 불필요하다.", "일시 복구만으로 재발 경로·가용성 영향 분석이 끝났다고 볼 수 없다.", "악성코드는 파일 삭제만으로 확산 범위 확인을 대신한다.", "파일 한 개 제거는 유입 경로·전파 범위·잔존 접근 수단을 확인하지 않는다.", [6,7]);
q('web-abuse', 'application', 2, '가상 홈페이지가 변조됐고 무단 계정 사용도 의심된다. 조사 범위는?', '웹 파일·DB·프로세스와 계정 행위를 함께 확인한다.', '웹 변조 결과와 비인가·오남용 경로가 연결될 수 있어 자료를 교차 확인한다.', '첫 화면 파일만 보고 나머지는 제외', '다른 페이지·저장소·권한 경로의 피해를 놓칠 수 있다.', '변조 문구의 언어만으로 행위자를 확정', '언어 표현은 실제 행위자의 신원을 입증하지 않는다.', '서비스가 열리면 계정 문제는 자동 해결', '가용성 회복과 계정 통제는 별도다.', [8, 9]);
q('trusted-restore', 'application', 2, '가상 서버 복구 후 재침입을 줄이려면?', '신뢰 가능한 복원본을 쓰고 취약점·지속성·자격 문제를 제거한 뒤 감시한다.', '기존 침입 경로와 남은 접근 수단을 없애야 복구가 지속될 수 있다.', '어느 시점의 백업이든 검증 없이 복원', '백업에도 오염이나 같은 취약점이 남을 수 있다.', '복구 직후 모든 감시를 중단', '잔여 문제와 재발을 확인할 기회를 잃는다.', '사고에 쓰인 자격을 계속 공유', '재사용 가능한 접근 수단을 유지한다.', [6, 7, 8, 9]);
q('preservation', 'concept', 2, '증거 수집 시 원본·수집 시각·담당·방법을 남기는 목적은?', '어떤 자료가 어떤 과정을 거쳤는지 검증 가능하게 하기 위해서', '분석 결론의 근거와 수집 과정의 신뢰성을 평가할 수 있다.', '모든 가설을 자동으로 사실로 바꾸기 위해서', '수집 이력은 가설의 참을 보장하지 않는다.', '사고 분석을 위해 원본을 반드시 공개해야 하기 때문', '보존과 무제한 공개는 다른 일이다.', '원본을 지워도 된다는 허가를 만들기 위해서', '수집 이력은 원본 보호를 대신하는 삭제 허가가 아니다.', [6, 7, 8, 9]);

objective(14, 'alert-support', '위기 경보와 원격·현장 지원의 선택', [5, 6],
  '경보 이름은 숫자만 외우기보다 피해 확산에 따라 협력과 대응 자원이 커지는 흐름으로 이해해야 한다.',
  ['교안은 관심·주의·경계·심각의 네 단계를 제시한다. 위험 가능성의 증가에서 국지적 피해, 여러 망·주요 기관의 피해, 광범위한 서비스 장애로 확장되는 교육적 흐름이다. 상위 단계의 대응은 하위 단계의 모니터링·초동 조치를 이어 가면서 비상 대응·공동 조정·긴급 조사·복구를 강화하는 구조로 설명한다.',
   '이 분류는 교안 문맥으로 한정하며 현재 국가 경보나 법적 의무를 자동 판정하는 규칙으로 쓰지 않는다. 조직의 실제 조치는 자산·영향·승인된 대응 계획에 따른다. 복구 지원은 단순한 접속 문제는 원격으로 가능할 수 있으나 긴급성·현장 필요·원격 접속 가능성에 따라 현장 지원을 선택한다. 비상 연락망과 내·외부 협력, 복구 범위·방법 합의도 지원의 일부다.'],
  '경보는 대응 강도를 조정하는 신호이며 실제 지원 방식은 접근성과 영향에 따라 선택한다.',
  [['원격 지원', '승인된 원격 경로로 분석·복구 지원', '경미하고 원격 처리 가능한 문제'], ['현장 지원', '직접 접근이 필요한 지원', '사설망·긴급 장비 확인'], ['경보 격상', '위험·영향에 맞춰 협력 강화', '비상 대응 체계 가동']],
  '가상 기관은 긴급 장애가 있지만 외부 원격 접속이 승인되어 있지 않다.',
  ['원격 경로가 가능한지와 보안·업무 제약을 확인한다.', '승인된 현장 지원 및 비상 연락 경로를 이용해 범위와 역할을 정한다.'],
  '원격이 편하다는 이유로 임의의 외부 접근 통로를 만들지 않는다.',
  '심각 단계가 아니면 초동 조치를 안 한다는 생각은 낮은 단계의 모니터링과 초기 대응을 무시한다.',
  '상위 단계로 갔다고 하위 단계의 감시를 멈출까?', '아니다. 교안의 흐름은 기존 조치를 계속하면서 집중 감시와 공조를 강화한다.', [4]);
q("alert-order", "concept", 1, "교안의 교육용 위기 경보 순서는?", "관심→주의→경계→심각", "위험 가능성에서 광범위 피해로 대응 강도가 커지는 네 단계다.", "관심→경계→주의→심각", "주의와 경계의 순서를 바꾸었다. 교안은 국지적 피해에서 더 넓은 피해로 강도를 높인다.", "주의→관심→경계→심각", "첫 두 단계가 반대다. 교안은 관심에서 주의로 이어진다.", "관심→주의→심각→경계", "마지막 두 단계가 반대다. 교안의 최고 단계는 심각이다.", [5]);
q('continue-measures', 'application', 2, '교안에서 주의에서 경계로 격상될 때 적절한 조치는?', '기존 모니터링을 계속하며 비상 대응과 집중 감시를 강화한다.', '상위 단계는 앞 단계의 대응을 이어 가면서 범위를 강화하는 구조다.', '기존 감시를 전부 종료한다.', '조치 연속성을 끊어 가시성을 낮춘다.', '연락망을 모두 폐기한다.', '공조 필요가 커지는 상황과 반대다.', '아직 심각이 아니므로 어떤 대응도 하지 않는다.', '하위 단계에도 모니터링과 초동 조치가 있다.', [6]);
q("remote-onsite", "application", 2, "가상 사설망 장비는 원격 접근이 불가능하며 긴급 점검이 필요하다. 적절한 지원은?", "승인된 현장 지원과 담당 간 비상 조정을 검토한다.", "접근성·긴급성 때문에 현장 조치가 필요한 상황이다.", "긴급성이 있으면 승인 없이 공개 원격 접속 포트를 먼저 연다.", "긴급 지원에서도 새로운 외부 접근 위험과 승인된 지원 경로를 고려해야 한다.", "원격 지원이 불가능하므로 담당 인계 없이 복구를 연기한다.", "현장 지원·비상 조정 대안이 있으므로 원격 제한만으로 지원을 포기할 수 없다.", "원격 접근이 안 되면 현장 인력에게도 자료 보존 없이 재설치를 지시한다.", "접근 방식 제약은 증거 보존·영향 검토를 생략할 근거가 아니다.", [5]);
q("warning-not-law", "evidence", 2, "교안의 심각 단계 설명만으로 현재 국가 경보와 법적 조치를 확정할 수 있나?", "현재 공식 상황과 규정을 별도로 확인해야 하며 이 자료는 교안 문맥이다.", "교육용 분류와 실제 시점의 공식 경보·의무는 구분해야 한다.", "교안 문장만으로 모든 현재 조치가 자동 확정된다.", "시점·관할·공식 결정의 차이를 무시한 판단이다.", "교안의 등급과 현재 공식 등급은 검증 없이 일대일 대응한다.", "같은 용어여도 적용 기준·공식 발령 사실을 별도 확인해야 한다.", "공식 경보가 없으면 조직 내부의 대응도 필요 없다.", "국가 경보 발령 여부만으로 개별 자산의 실제 위험과 대응 필요성을 배제할 수 없다.", [5,6]);
q("support-scope", "application", 2, "외부 지원팀이 가상 사고 복구를 돕기 전 합의할 내용은?", "지원 범위·방법·접근 권한·연락·증거 처리 책임", "누가 무엇을 어떤 방식으로 다룰지 명확해야 조치와 자료 보호가 연결된다.", "기술 복구 목표만 정하고 접근 권한·증거 처리는 생략", "복구 목적이 있어도 자료 보호·승인 범위·보존 책임을 명확히 해야 한다.", "지원 인력 명단만 받고 조치 범위·연락 경로는 정하지 않음", "참여자 신원만으로 누가 무엇을 승인·변경·보존할지 정해지지 않는다.", "지원팀이면 모든 변경을 사후 기록 없이 허용", "접근 범위와 추적 가능성이 없어 조치 영향과 증거 보존을 검증하기 어렵다.", [5]);

objective(14, 'windows-live', 'Windows 초기 조사·연결·프로세스와 루트킷', [9, 10, 11, 12, 18],
  '열린 포트 하나를 보고 악성이라고 단정하거나 정상처럼 보이는 프로세스 목록만 믿으면 실제 상태를 오해할 수 있다.',
  ['Windows 초기 조사는 계정·그룹, 포트·프로세스·세션, 서비스·공유 자원, 중요 파일 무결성, 시작 항목과 웹 서버 설정을 함께 살핀다. 교안의 ipconfig는 네트워크 구성, netstat -an은 주소·포트·연결 상태 확인의 예다. 포트를 실제 프로세스에 연결하는 자료는 별도로 확보하고 경로·서명·실행 주체·시작 시각·부모 관계를 업무 기준선과 비교한다.',
   '루트킷은 프로세스·파일·레지스트리·연결 등을 숨겨 관찰을 왜곡할 수 있다. 권한 획득에 관련될 수 있으나 모든 루트킷이 최초 관리자 권한 획득 도구라는 뜻은 아니다. 교안의 fport·promiscdetect·IceSword·FileMon은 구형 환경의 조사 사례다. 특히 그림의 어댑터 열기 실패는 탐지 성공이 아니다. 현대 보충: Process Explorer는 프로세스·핸들·모듈 조사, Process Monitor는 파일·레지스트리·프로세스 활동 기록에 쓰이며 FileMon을 메모리 덤프 도구로 외우지 않는다.'],
  '연결과 실행 주체를 교차 확인하고 감염 의심 시스템의 출력·도구 실패를 무조건 신뢰하지 않는다.',
  [['네트워크 상태', '주소·포트·연결 관찰', '대기 포트와 연결 목록'], ['프로세스 조사', '실행 파일·계정·관계 확인', 'Process Explorer의 실행 경로'], ['활동 추적', '시간에 따른 파일·레지스트리 동작', 'Process Monitor 이벤트']],
  '가상 서버에 낯선 연결이 있고 프로세스는 정상 이름을 사용한다.',
  ['연결의 실제 프로세스와 경로·계정·시각을 확인한다.', '서명·기준 파일·다른 센서 자료를 대조하고 조사 도구가 남기는 상태 변화도 기록한다.'],
  '프로세스 이름만으로 정상·악성을 확정하지 않는다.',
  '루트킷 감지가 안 되었으니 침해가 없다는 생각은 은폐·탐지 범위·수집 실패를 무시한다.',
  '네트워크 어댑터를 열 수 없다는 출력은 감염 없음의 증거일까?', '아니다. 해당 검사가 실패한 것이므로 도구·권한·호환성을 확인하고 결과를 미확인으로 남겨야 한다.', [5]);
q("netstat-scope", "concept", 1, "교안의 netstat -an 출력이 중심적으로 보여 주는 것은?", "네트워크 주소·포트와 연결 상태", "연결·대기 상태를 보는 자료이며 실제 행위 분석은 다른 자료가 필요하다.", "각 연결의 사용자 인증 성공 여부", "네트워크 연결·대기 상태만으로 서비스가 계정을 검증한 결과를 알 수 없다.", "모든 연결의 실행 파일 경로와 서명", "질문의 netstat -an만으로 프로세스별 실행 파일 정체까지 확인되었다고 볼 수 없다.", "각 연결의 악성코드 이름과 유출 자료", "주소·포트 관찰은 프로그램 정체·실제 자료 이동 내용의 직접 증거가 아니다.", [9,10]);
q("process-name", "evidence", 2, "가상 프로세스가 정상 시스템 이름을 사용한다. 추가 확인에 적절한 것은?", "실행 경로·계정·서명·부모 관계와 기준선", "이름은 위장 가능하므로 실제 파일과 실행 맥락을 조사해야 한다.", "시스템 이름과 같으므로 정상으로 종결", "이름은 위장 가능해 실제 실행 경로와 맥락을 검증하지 못한다.", "같은 이름 프로세스를 전부 삭제하고 나중에 정체를 확인", "정상 서비스 영향과 증거 손실을 고려하지 않은 조치다.", "프로세스 ID가 작으면 시스템 프로세스로 신뢰", "PID 자체는 파일 출처·권한·실행 행위의 정당성을 증명하지 않는다.", [11,12]);
q("rootkit", "concept", 2, "루트킷이 조사에서 만드는 중요한 어려움은?", "시스템의 파일·프로세스·연결 관찰을 은폐·왜곡할 수 있다.", "감염 의심 시스템의 자체 출력만으로 전체 상태를 신뢰하기 어렵게 한다.", "프로세스 목록 하나만 확보하면 은폐 가능성은 완전히 배제된다.", "루트킷은 자체 출력을 왜곡할 수 있어 다른 정보원과 교차 확인해야 한다.", "반드시 최초 권한 획득부터 모든 공격을 혼자 수행한다.", "은폐·지속성과 최초 권한 획득은 항상 동일한 기능이 아니다.", "파일 해시 하나가 정상본과 같으면 루트킷 전체가 배제된다.", "한 파일의 동일성은 다른 파일·메모리·설정의 은폐 상태를 검증하지 않는다.", [10,11]);
q('tool-failure', 'evidence', 2, '교안의 도구 화면에 어댑터 열기 실패가 표시된다. 정확한 해석은?', '그 어댑터에 대한 검사가 수행되지 못했다.', '도구 실패를 정상 또는 감염 없음으로 바꾸어 읽으면 안 된다.', '어댑터가 정상임이 검증됐다.', '정상 확인이 아니라 수집 실패다.', '스니핑 악성코드가 반드시 탐지됐다.', '실패 메시지는 악성 행위의 직접 증거가 아니다.', '모든 네트워크 조사 방법이 영구적으로 불가능하다.', '다른 도구·권한·환경에서 대안 확인이 가능할 수 있다.', [10]);
q("filemon", "contrast", 2, "교안 FileMon 설명을 현대 도구 문서로 보정한 것은?", "파일 접근 추적과 메모리 덤프를 구분하며 Process Monitor는 파일·레지스트리 활동 등을 기록한다.", "FileMon 계열의 활동 관찰을 메모리 전체 수집과 같은 기능으로 보면 안 된다.", "FileMon은 파일 활동 기록과 동시에 항상 완전한 메모리 덤프를 만든다.", "활동 추적과 메모리 획득은 다른 작업이며 완전 덤프를 일반 기능으로 보면 안 된다.", "Process Explorer는 파일·레지스트리 이벤트를 시간순으로 모두 기록하는 도구다.", "프로세스·핸들·모듈 조사와 Process Monitor의 활동 추적 중심 역할을 혼동했다.", "Process Monitor의 파일 접근 기록은 그 자체로 전체 메모리 내용이다.", "파일 이벤트 기록만으로 프로세스 메모리의 전체 바이트를 수집했다고 볼 수 없다.", [12]);

objective(14, 'windows-persistence', '레지스트리·자동 실행·서비스·공유와 무결성', [9, 11, 12, 13, 14, 15],
  '파일 한 개를 지워도 다시 실행된다면 시작 항목이나 서비스 같은 지속성 경로가 남았을 수 있다. 자동 실행이 존재하는 것과 악성이라는 판단은 구분한다.',
  ['레지스트리는 소프트웨어·사용자·시스템 설정과 사용 흔적을 담는 정보원이다. Run·RunOnce 등의 시작 항목, 서비스, 파일 연결, 로그온 관련 설정과 웹 서버 가상 디렉토리는 실행·접근 경로를 설명하는 데 도움이 된다. 최근 문서·열기 기록·원격 접속 흔적은 활동 단서지만 기록 누락·공유 계정·정리 동작 때문에 단독으로 사용자의 행위를 확정하지 않는다.',
   '교안의 경로 목록에는 구형 버전 의존 위치와 철자·띄어쓰기 문제가 있으므로 일괄 복사해 수정하는 지침으로 사용하지 않는다. 현대 보충: 지원되는 도구·문서로 해당 OS의 자동 실행 위치와 실행 대상을 확인한다. 정상 업데이터·드라이버도 자동 실행을 사용하므로 경로·서명·설치 이력·승인을 비교한다. 조사 전 삭제·초기화는 증거와 정상 기능을 잃을 수 있어 수집·분석·승인된 제거를 구분한다.'],
  '자동 실행 위치와 실제 대상을 조사하고 정상 기준선·변경 이력으로 해석한 뒤 조치한다.',
  [['시작 항목', '부팅·로그온 등에서 실행 연결', '정상 업데이트 프로그램'], ['사용 흔적', '과거 활동을 추정하는 단서', '최근 문서 목록'], ['무결성 비교', '기준 파일과 현재 파일의 차이 확인', '동일 버전 배포본과 해시 비교']],
  '가상 서버에서 새 시작 항목이 발견됐지만 승인된 프로그램 설치도 있었다.',
  ['시작 항목의 원본 값과 실행 파일·계정·변경 시각을 기록한다.', '설치 승인·서명·기준선과 비교한 뒤 악성 여부와 제거 필요성을 판단한다.'],
  '자동 실행 존재만으로 삭제하지 않고 변경의 의미를 확인한다.',
  '최근 문서 항목 하나면 특정 사람이 파일 내용을 읽었다는 사실까지 확정한다는 생각은 생성 조건과 사용자 공유를 무시한다.',
  '자동 실행 항목의 서명이 유효하면 모든 행위가 정상일까?', '서명은 출처·무결성 판단의 단서지만 실제 실행 인수·경로·정책·행위까지 모두 정당화하지는 않는다.', [6, 10]);
q("autorun", "concept", 1, "공격자가 자동 실행 위치를 악용하는 주요 목적은?", "재부팅·로그온 뒤에도 악성 실행을 다시 시작하려는 것", "시작 항목은 실행의 반복·지속성을 만드는 경로가 될 수 있다.", "실행 중인 프로세스만 종료하여 다음 로그온 실행까지 막는 것", "현재 종료와 시작 항목에 의한 재실행은 별개이므로 지속성을 설명하지 못한다.", "로그 파일 하나를 변경해 이후 모든 실행 기록을 없애는 것", "로그 훼손과 시작 항목을 이용한 반복 실행은 구분해야 한다.", "정상 프로그램의 서명을 확인하여 악성 실행을 방지하는 것", "공격자의 실행 지속 목적과 관리자의 정체 검증 활동을 혼동했다.", [13,14]);
q('new-startup', 'application', 2, '가상 서버에 새 Run 항목과 승인된 설치 이력이 있다. 적절한 조치는?', '항목·파일·서명·설치 이력을 대조하여 변경의 정당성을 확인한다.', '정상 프로그램도 자동 실행을 쓰므로 대상과 맥락을 함께 검토한다.', '새 항목이면 모두 악성으로 삭제', '정상 기능과 증거를 훼손할 수 있다.', '승인 설치가 한 건이라도 있으면 모든 새 항목을 허용', '관련 없는 변경이나 설치 오용 가능성을 놓친다.', '키 이름이 Run이므로 원문을 기록할 필요가 없다.', '실제 실행 대상·값이 분석에 필요하다.', [13, 14]);
q('mru', 'evidence', 3, '최근 문서 기록에 파일명이 있다. 결론 범위는?', '관련 활동 단서이며 생성 조건·사용자·다른 기록과 대조해야 한다.', '흔적 하나가 파일 내용 열람자·의도·전달까지 모두 입증하지 않는다.', '특정 직원이 모든 내용을 읽고 유출한 것이 확정된다.', '단서의 의미보다 훨씬 넓은 결론이다.', '파일명 기록은 언제나 악성코드가 만든 것이다.', '정상 사용도 기록을 만든다.', '기록이 없으면 파일이 존재한 적도 없다.', '누락·정리·설정 차이 가능성을 무시한다.', [14]);
q('registry-paths', 'application', 2, '교안의 오래된 레지스트리 경로를 현재 OS 조사에 사용할 때는?', 'OS별 공식 위치·지원 상태를 확인하고 조사 목적에 맞게 적용한다.', '철자·버전 의존성이 있어 옛 목록을 그대로 조작 지침으로 삼으면 안 된다.', '띄어쓰기와 철자 차이를 무시하고 모두 삭제', '실제 경로를 오인하고 정상 설정을 파괴할 수 있다.', '옛 목록에 없는 시작 위치는 절대 없다.', 'OS와 제품의 자동 실행 경로는 다양하다.', '경로 목록만 있으면 모든 지속성이 제거된다.', '목록 보유와 실제 조사·제거 결과는 다르다.', [13, 14]);
q("before-remove", "application", 2, "의심 자동 실행 항목을 찾았을 때 바로 삭제하기 전에 필요한 것은?", "원본·실행 대상·변경 이력을 보존하고 영향과 제거 방법을 검토한다.", "조사와 정상 기능을 보존하면서 근거 있는 제거를 할 수 있다.", "관련 기록도 함께 지워 간단히 정리", "원인·범위와 조치 결과 검증에 필요한 자료를 잃는다.", "이상 여부와 무관하게 원본 항목을 먼저 비활성화하고 기록은 나중에 복원", "긴급 위험을 고려해야 하지만 선행 보존·영향 검토 없이 변경하면 증거와 정상 기능을 잃을 수 있다.", "서명이 유효하면 실행 인수와 승인 내역을 보지 않고 유지", "유효 서명만으로 실제 인수·경로·정책·행위의 정당성을 모두 입증하지 못한다.", [9,13,14]);

objective(14, 'windows-events-web', '이벤트 버전·IIS 구조·웹 로그의 교차 분석', [15, 16],
  '이벤트 번호는 운영체제와 제공자 문맥이 있어야 의미가 있다. 비밀번호 변경·세션 재연결 같은 정상 동작을 곧바로 공격이라고 읽지 않는다.',
  ['교안의 529 계열·539·624 등의 보안 이벤트는 구형 Windows 문맥이며 최신 환경에는 해당 버전의 감사 문서를 확인한다. 예를 들어 지원되는 감사 구성에서 4625는 로그인 실패를 나타내지만 그 원인이 악성 추측인지, 만료·정책 제한·잘못된 설정인지는 상태 코드와 로그온 유형·계정·출처를 봐야 한다. 계정 생성·서비스 시작·암호 변경·원격 세션 재연결도 승인된 관리 행위일 수 있다.',
   '웹 조사에서는 파일 변경 시각만 보지 않고 변경 이전의 요청·계정·프로세스·사이트 및 가상 디렉토리 설정·로그 위치와 권한을 연결한다. 교안의 MetaEdit와 패턴 검색은 과거 조사 사례다. 특정 단어 검색은 의심 후보를 줄이는 수단이며 코드·로그의 일치가 웹쉘 성공을 확정하지 않는다. 검색 결과가 없어도 변형·인코딩·로그 누락이 있을 수 있으므로 원본 보존과 다른 자료의 확인이 필요하다.'],
  '이벤트 제공자·버전·필드와 실제 웹 변경 결과를 연결해 사실과 의심을 나눈다.',
  [['로그인 실패', '인증 시도가 실패한 관찰', '4625와 실패 상태 코드'], ['계정 생성', '새 계정이 생긴 관찰', '관리 승인과 생성 주체 확인'], ['패턴 검색', '알려진 표현의 후보 탐색', '웹 로그와 파일 사본에서 단서 찾기']],
  '가상 웹 서버에서 서비스 재시작과 의심 요청이 가까운 시각에 있다.',
  ['정기 배포·관리 승인과 이벤트 제공자·조치 주체를 확인한다.', '웹 파일·설정·프로세스 변경을 대조해 두 기록의 관계와 실제 영향을 검증한다.'],
  '근접한 시각만으로 서비스 재시작이 웹 침입의 결과라고 단정하지 않는다.',
  '검색 결과가 없으니 웹쉘이 없다는 생각은 패턴의 한계와 누락·변형을 놓친다.',
  '암호 변경 이벤트는 무조건 계정 탈취일까?', '아니다. 변경한 주체·승인·계정·다른 로그인 및 피해 증거를 함께 확인해야 한다.', [7, 11]);
q("event-version", "evidence", 2, "교안의 보안 이벤트 529를 현재 Windows 조사에 적용할 때 필요한 것은?", "OS 버전·이벤트 제공자·감사 정책과 공식 의미를 확인한다.", "구형 번호를 모든 Windows의 보편 규칙으로 적용하면 수집과 해석이 틀릴 수 있다.", "모든 Windows가 529만으로 로그인 실패를 기록한다고 가정", "버전별 감사 체계 차이를 무시한 일반화다.", "이벤트 번호가 같으면 제공자가 달라도 의미는 항상 동일하다고 가정", "번호는 제공자·버전 문맥과 함께 해석해야 한다.", "번호가 다르면 로그인 실패가 없었다고 결론", "다른 번호·설정·제공자로 기록될 수 있어 부재를 확정하지 못한다.", [15]);
q('4625', 'application', 2, '가상 로그의 Microsoft 보안 감사 4625가 제시된다. 추가로 확인할 정보는?', '실패 상태·로그온 유형·계정·출처와 관련 성공 기록', '로그인 실패의 원인과 공격 가능성·계정 영향을 구분하는 데 필요하다.', '4625이므로 침입 성공을 즉시 확정', '실패 이벤트와 인증 성공은 다르다.', '모든 실패는 반드시 비밀번호 추측 공격', '정책·만료·서비스 설정 등 다른 원인도 가능하다.', '이벤트 제목만 남기고 필드를 지운다.', '원인과 주체·범위를 분석할 단서를 잃는다.', [15]);
q('account-service', 'evidence', 2, '가상 서버에 계정 생성과 서비스 재시작이 기록됐다. 적절한 해석은?', '조치 주체·승인·변경 목적과 다른 이상 행위를 대조한다.', '정상 관리와 공격 모두 가능하므로 행위의 맥락이 필요하다.', '계정이 새로 생겼으므로 공격자가 확정됐다.', '생성 사실만으로 무단 여부를 판정하지 못한다.', '서비스 재시작은 언제나 백도어 설치다.', '업데이트·정상 운영도 재시작을 유발한다.', '승인 기록은 기술 조사에 필요 없다.', '관리 행위와 비인가 변화를 구분하는 중요한 보완 자료다.', [15]);
q('web-signature', 'evidence', 2, '가상 파일 사본에서 웹쉘 관련 의심 문자열이 검색됐다. 다음 단계는?', '문맥·실제 실행 경로·웹 요청·변경 이력을 대조한다.', '문자열 일치는 후보 단서이며 실행과 피해 범위는 추가 증거가 필요하다.', '문자열 한 번이면 모든 웹 파일이 감염됐다.', '일치 범위를 전체 자료로 확대할 근거가 없다.', '예제 문서에 있어도 반드시 서버가 실행했다.', '텍스트 존재와 실행 결과를 혼동한다.', '조사 없이 원본을 덮어써 흔적을 지운다.', '증거 보존과 원인 분석을 방해한다.', [16]);
q("iis-virtual", "application", 2, "가상 IIS에 낯선 가상 디렉토리가 있다. 확인할 것은?", "실제 연결 경로·권한·생성 이력·로그 설정과 접근 기록", "가상 경로가 어떤 파일과 실행·접근 권한을 노출하는지 파악해야 한다.", "가상 경로의 표시 이름만 바꾸고 종료", "이름 변경만으로 실제 연결 경로·실행 및 접근 권한이 바뀌지 않는다.", "가상 경로이면 실제 저장 위치를 조사할 필요 없음", "가상 디렉토리도 실제 파일 위치에 대응하므로 그 범위와 권한을 확인해야 한다.", "사이트가 승인됐으면 모든 가상 디렉토리도 승인됐다고 판단", "사이트 승인만으로 새로 연결된 경로·권한·변경 이력을 설명하지 못한다.", [15,16]);

objective(14, 'linux-live-account', '리눅스 구성·휘발성 정보·계정·접속 조사', [16, 17, 18],
  '접속자 이름이나 해외 주소만으로 침해를 판단하면 정상 관리자를 오인할 수 있다. 실행 주체와 권한, 행위, 기준선의 연결을 확인한다.',
  ['리눅스 조사는 배포판·커널·패치, 서비스·망 구성·보안장비 정보를 먼저 파악한다. 살아 있는 프로세스, 열린 파일·소켓, 라우팅·주변 통신 정보, 현재 접속자는 시간이 지나면 바뀌는 자료다. 교안의 ps·top·pstree, lsof·fuser, ifconfig·netstat·arp, w·who·last는 서로 다른 관찰 예시이며 모든 배포판에 같은 명령과 로그 경로가 있는 것은 아니다.',
   '계정 파일에서 UID 0은 높은 권한의 계정이므로 승인되지 않은 추가 계정과 변경 이력을 조사한다. 하지만 root 로그인 자체가 침해 증거는 아니다. shadow 구성에서는 passwd의 x가 비밀번호 없음이 아니라 별도 검증 정보 사용을 가리킬 수 있다. utmp·wtmp, 인증·시스템 로그, 셸 기록은 상호 보완하며 누락·설정·수정 가능성을 고려한다. 국외 IP는 위치 단서이지 행위자의 신원이나 악성 의도를 입증하지 않는다.'],
  '계정 권한·접속 출처·실제 프로세스 행위를 승인 이력과 대조한다.',
  [['현재 상태', '지금 살아 있는 실행·연결 정보', '프로세스·열린 파일'], ['인증·접속 이력', '과거 세션·인증의 기록', 'last와 인증 기록'], ['계정 정의', 'UID·홈·셸 등 계정 속성', 'passwd와 제한된 shadow']],
  '가상 리눅스 서버에 UID 0 계정 하나가 추가되고 해외 주소 접속이 기록됐다.',
  ['계정 생성 승인·시각·로그인 주체와 키·세션 이력을 확인한다.', '해당 세션의 프로세스·명령 흔적·파일 변화를 대조해 무단 권한·행위를 조사한다.'],
  '고권한 계정 변경을 우선 조사하되 주소나 root 사용만으로 범인을 확정하지 않는다.',
  '셸 기록에 없으면 명령이 실행되지 않았다는 생각은 기록 설정·비대화형 실행·삭제 가능성을 무시한다.',
  'passwd의 비밀번호 필드가 x라면 비밀번호가 없다고 판단해도 될까?', '아니다. 일반적인 shadow 구성에서는 별도의 shadow 기록에서 검증 정보를 확인하는 표시다.', [9]);
q('volatile', 'contrast', 2, '리눅스의 현재 프로세스·소켓 정보와 디스크 파일의 차이로 적절한 것은?', '현재 실행·연결 상태는 종료나 시간 경과로 쉽게 사라질 수 있다.', '휘발성 상태는 수집 시점이 중요하며 디스크 자료와 보존 특성이 다르다.', '현재 프로세스 목록은 전원을 꺼도 그대로 남는다.', '살아 있는 실행 상태는 전원 차단으로 소실될 수 있다.', '디스크 파일은 어떤 상황에서도 절대 변하지 않는다.', '디스크 자료도 쓰기·삭제·오염될 수 있다.', '두 종류는 조사 목적상 완전히 같은 자료다.', '관찰 대상과 시간·보존 특성이 다르다.', [16, 17]);
q('uid-zero', 'application', 2, '가상 서버에 승인 내역에 없는 새 UID 0 계정이 있다. 적절한 대응은?', '계정 생성·변경·인증 이력과 실제 사용을 우선 조사한다.', '고권한 신규 계정은 중요 단서이며 생성 주체·승인·행위의 확인이 필요하다.', 'UID 0은 권한이 없으므로 무시한다.', '리눅스에서 UID 0은 높은 권한을 나타낸다.', '모든 정상 root 계정도 즉시 악성으로 확정한다.', '정상 계정과 승인 없는 추가 계정을 구분해야 한다.', '계정 이름이 평범하면 승인 확인을 생략한다.', '이름보다 UID·생성 경위·사용 행위가 중요하다.', [17, 18]);
q('shadow-x', 'concept', 2, '일반적인 shadow 구성의 passwd 비밀번호 필드가 x일 때 올바른 의미는?', '별도의 shadow 기록을 사용하는 표시일 수 있다.', 'x를 비밀번호 원문이나 비밀번호 없음으로 해석하면 안 된다.', '사용자가 실제로 쓰는 원문 비밀번호가 x다.', '자리표시자와 실제 인증 비밀을 혼동했다.', '어떤 인증도 필요 없는 계정임이 확정된다.', 'shadow 구성에서는 별도의 검증 정보와 인증 정책을 확인해야 한다.', '계정이 반드시 공격자가 만든 것이다.', '정상 계정에서도 일반적으로 사용하는 구성이다.', [17]);
q('foreign-ip', 'evidence', 2, '가상 서버의 root 세션 출처가 해외로 분류된다. 현재 가능한 결론은?', '고권한 접속의 승인·인증·세션 행위를 추가 조사할 단서다.', '지리 분류와 계정명만으로 무단 접근이나 실제 행위자를 확정하지 못한다.', '해외이면 모두 침해다.', '출장·VPN·관리 경로와 주소 분류 오차 등 정상 설명이 있을 수 있다.', 'root 이름이면 모두 정상이다.', '계정 탈취나 무단 사용 가능성을 배제하지 못한다.', '해당 IP의 국가가 곧 공격자 국적이다.', '주소 위치와 실제 사람의 신원·국적은 다르다.', [17]);
q("history-limit", "evidence", 2, "가상 서버의 셸 기록에는 의심 명령이 없다. 적절한 평가는?", "기록 설정·비대화형 실행·보존 상태를 확인하고 다른 자료와 대조한다.", "셸 기록은 완전한 감사 기록이 아니므로 부재만으로 실행을 배제할 수 없다.", "명령 실행은 절대 없었다고 확정한다.", "셸 기록의 누락·설정·보존 한계를 고려하지 않은 결론이다.", "대화형 셸 기록이 없으므로 서비스의 비대화형 실행도 없었다고 본다.", "비대화형 실행은 같은 기록 경로에 남지 않을 수 있어 별도 자료가 필요하다.", "현재 프로세스 목록에 없으면 과거 실행 가능성도 배제한다.", "프로세스는 이미 종료됐을 수 있으므로 현재 상태만으로 과거 활동을 배제하지 못한다.", [17]);

objective(14, 'linux-time-integrity', '시간 속성·특수 권한·정상 기준 파일 비교', [9, 17, 18],
  'ctime을 생성 시각으로 읽으면 오래된 파일의 권한 변경을 새 악성파일 생성으로 오인할 수 있다. 무결성 비교도 무엇과 비교했는지에 따라 의미가 달라진다.',
  ['리눅스의 mtime은 내용 수정, ctime은 inode 상태 변경과 관련되며 내용 쓰기·소유자·권한 변경 등으로 갱신될 수 있다. 생성 시각은 지원되는 환경의 btime 등 별도 정보다. 따라서 교안의 최근 ctime 검색은 최근 생성 파일만 찾는 방식이 아니다. 시간 속성은 조사 범위를 좁히는 단서이며 정확한 생성 원인과 행위자는 다른 기록으로 확인한다.',
   'setuid·setgid 파일은 실행 권한 맥락을 바꾸는 정상 용도가 있으나 승인 없는 추가·변경은 우선 조사한다. 숨김 이름이나 /tmp·/dev의 낯선 파일도 위치·유형·용도·패키지 기준선과 비교한다. 해시 일치는 동일 바이트를 확인하는 단서이며 신뢰할 수 있는 같은 버전의 기준이 중요하다. NSRL 같은 알려진 소프트웨어 자료와 알려진 악성 지표는 역할이 다르고, 목록에 없거나 정상 해시와 일치한다는 이유만으로 호스트 전체를 악성·정상으로 확정하지 않는다.'],
  '시간·권한·해시·경로는 기준선과 다른 증거를 결합해 해석한다.',
  [['mtime', '파일 내용의 최종 수정 시각', '내용 쓰기 후 갱신'], ['ctime', 'inode 상태의 최종 변경 시각', '권한 변경 후 갱신'], ['btime', '지원되는 경우 생성 시각', '파일시스템의 생성 정보']],
  '가상 파일은 한 달 전에 생성됐지만 오늘 권한만 바뀌었다.',
  ['ctime과 mtime·가능한 btime을 구분하여 권한 변경의 영향을 해석한다.', '권한 변경 승인·패키지 기준·인증 기록을 대조하고 최근 ctime을 새 파일 생성으로 보고하지 않는다.'],
  '상태 변경 시각과 생성 시각을 분리해 파일의 시간선을 설명한다.',
  '해시가 기준과 다르면 무조건 공격이라는 생각은 정상 업데이트와 버전 차이를 놓친다.',
  'NSRL에 없는 파일은 모두 악성일까?', '아니다. 자료집의 범위 밖인 정상 파일도 있으므로 출처·패키지·행위와 다른 지표를 조사해야 한다.', [8, 10]);
q("ctime", "concept", 1, "리눅스 ctime의 정확한 의미는?", "inode 상태가 마지막으로 변경된 시각", "권한·소유자·내용 쓰기 등에 영향을 받으며 생성 시각과 구분한다.", "파일 내용만 마지막으로 수정된 시각", "내용 수정의 mtime과 구분한다. ctime은 권한·소유자 변경 등에도 갱신된다.", "파일 데이터가 마지막으로 읽힌 시각", "읽기 접근의 atime과 inode 상태 변경의 ctime은 다른 속성이다.", "파일이 최초로 생성된 시각만", "생성 시각인 btime 등과 구분하며 ctime은 생성 후 상태 변경에도 갱신된다.", [17]);
q("chmod-time", "application", 2, "가상 파일은 한 달 전 생성됐고 오늘 내용 변경 없이 권한만 바뀌었다. 적절한 해석은?", "ctime이 갱신될 수 있지만 그것이 오늘 생성됐다는 뜻은 아니다.", "권한 변경은 inode 상태 변화이며 생성 시각을 다시 정하지 않는다.", "오늘 ctime이면 반드시 오늘 생성된 파일이다.", "생성과 inode 상태 변경을 혼동했다.", "권한만 바뀌면 mtime과 생성 시각도 반드시 오늘로 바뀐다.", "권한 변경은 ctime과 관련되지만 내용 수정·생성 시각을 모두 재설정하는 것은 아니다.", "내용이 안 바뀌었으므로 ctime도 갱신될 수 없다.", "내용 쓰기 외에도 권한·소유자 같은 inode 상태 변화로 ctime이 갱신될 수 있다.", [17]);
q('special-bits', 'evidence', 2, '가상 서버에서 새 setuid 실행 파일이 발견됐다. 적절한 조사는?', '패키지·소유자·권한·변경 승인·실제 행위를 기준선과 대조한다.', '특수 권한은 정상 용도가 있지만 무단 변경이면 높은 영향이 있어 확인해야 한다.', 'setuid는 언제나 악성이라 원본 보존 없이 삭제', '정상 시스템 기능과 증거를 잃을 수 있다.', 'root 소유면 어떤 파일도 정상', '소유자만으로 출처와 행위의 정당성이 보장되지 않는다.', '숨김 파일만 위험하므로 무시', '위험은 이름뿐 아니라 실제 권한과 실행 맥락에 달려 있다.', [17]);
q("hash-baseline", "evidence", 3, "가상 시스템 파일의 해시가 작년 정상본과 다르다. 판단에 필요한 것은?", "현재 버전의 신뢰 기준·업데이트·서명·행위와의 대조", "정상 버전 변경도 바이트 차이를 만들 수 있어 비교 기준을 맞춰야 한다.", "차이만으로 악성 변조를 즉시 확정", "정상 업데이트·버전 차이를 배제하지 않은 판단이다.", "파일 이름이 같으므로 버전 차이는 확인하지 않고 같은 기준으로 본다.", "동일한 이름으로 정상 버전이 바뀔 수 있어 비교 기준의 출처·버전을 맞춰야 한다.", "해시가 한 번 맞으면 모든 호스트 상태가 정상", "파일 하나의 동일성은 다른 지속성·설정·행위를 검증하지 않는다.", [9,17,18]);
q('nsrl', 'contrast', 2, 'NSRL 같은 알려진 소프트웨어 참조 자료의 적절한 사용은?', '알려진 파일 식별에 참고하고 미등재 파일은 추가 조사한다.', '자료집 범위와 파일의 출처·행위를 고려해야 하며 등재 여부가 호스트 판정 전체를 대신하지 않는다.', '목록에 없으면 모두 악성으로 분류', '참조 자료에 수록되지 않은 정상 소프트웨어도 있다.', '목록에 정상 파일 하나가 있으면 침해 전체를 배제', '나머지 파일·설정·행위의 상태를 확인하지 않았다.', '알려진 정상과 알려진 악성 해시의 의미는 완전히 같다.', '두 자료는 식별 목적과 결론의 방향이 다르다.', [17, 18]);

correction(14, 1, [1, 2, 3, 4], '과거 법 조문·일반/중대 분류·다섯 유형·조사 착수 표를 현재 보편 법적 판단으로 읽을 수 있다.', '교안 PDF 1~4쪽의 분류·착수 표는 역사적 교육 문맥이다. 현대 보충인 NIST SP 800-61 Rev.3 §1(인쇄 2쪽)의 사고 개념에는 정당한 권한 없는 실제 또는 임박한 기밀성·무결성·가용성 위협, 법·보안 정책·절차·허용 가능한 사용 정책 위반이나 임박한 위반 위협도 포함된다. 모든 이벤트가 사고는 아니므로 조직 기준·증거로 판단한다. NIST의 개념을 국내 현행 법적 정의·공식 등급으로 대체하지 않는다.', '법 조문 번호와 현행 법적 의무를 점수 문항에 쓰지 않고 분류 문맥과 영향 판단을 평가한다.', 'contextualized', ['ir', 'irDefinition', 'first']);
correction(14, 2, [2], '2003년 CERT/CC KR 관련 기관 연혁이 짧게 제시되어 명칭·설립 시점의 동일성이 불명확하다.', '이 작업에서 정확한 기관 연혁을 독립 확정하지 않았다. CERT의 협력·예방·대응 역할만 학습하고 특정 설립 연도는 제외한다.', '2003년이나 기관명 변화 순서는 채점하지 않는다. FIRST 자료는 대응 서비스의 역할 참고이며 그 연혁을 입증하는 출처가 아니다.', 'excluded', ['first']);
correction(14, 3, [3, 4, 6, 7, 8, 9], '네트워크 차단·복구 중심 표에 휘발성 증거 보존과 조치 기록의 판단 기준을 보충할 필요가 있다.', '가능한 격리·확산 위험·안전·업무 영향과 증거를 함께 평가한다. 일괄 전원 차단은 휘발성 자료를 잃고 일괄 가동 유지도 위험하다. 조치 시각·담당·방법과 원본을 보존한다.', '항상 전원 차단·항상 가동을 정답으로 두지 않고 조건별 보호·보존·복구를 평가한다.', 'contextualized', ['forensic', 'ir']);
correction(14, 4, [5, 6], '관심·주의·경계·심각 표를 현재 국가 경보·법적 의무의 자동 판정 규칙으로 오해할 수 있다.', '교안 시점의 교육용 단계·대응 연속성으로 한정한다. 실제 국가 경보·의무는 현재 공식 상황을 별도 확인해야 한다.', '과거 분류의 흐름만 평가하고 현재 경보 발령 사실이나 법률 주장을 만들지 않는다.', 'contextualized', ['ir']);
correction(14, 5, [9, 10, 11, 12, 18], 'FileMon을 MEM 덤프 기능으로 설명하고 구형 도구·루트킷 정의를 제시한다. p10 화면에는 어댑터 열기 실패도 있다.', 'FileMon 계열은 파일 활동 추적이며 메모리 획득과 다르다. Process Monitor와 Process Explorer의 기능을 구분한다. 실패 출력은 미검사다. 루트킷의 은폐와 최초 권한 획득을 항상 동일시하지 않는다.', '과거 도구 설치·사용을 요구하지 않고 수집 대상·성공/실패·관찰 한계를 평가한다.', 'verified', ['proc', 'procexp', 'netstat', 'forensic']);
correction(14, 6, [13, 14, 15], '레지스트리 경로에 구형 위치·철자와 띄어쓰기 문제가 있고 흔적을 공격자 행위로 단정할 수 있다.', '목록을 현재 OS 수정 명령으로 복사하지 않는다. 지원 문서·도구로 자동 실행과 사용 흔적의 실제 위치·의미를 확인하고 승인 이력과 대조한다.', '오래된 경로 철자 암기 대신 실행 대상·정상 기준선·원본 보존을 평가한다.', 'contextualized', ['autoruns', 'proc']);
correction(14, 7, [15], '529 계열·539·624 등 구형 이벤트와 암호 변경·세션 재연결을 공격으로 연결하는 단정이 있다.', '이벤트는 OS·제공자·감사 정책에 따라 해석한다. 현대 문서의 4625는 실패이며 상태·유형·출처가 필요하다. 계정 생성·암호 변경·서비스 재시작은 승인된 정상 행위일 수도 있다.', '과거 번호를 현행 보편 번호로 채점하지 않고 관찰·승인·피해를 구분한다.', 'verified', ['auditmap', 'fail']);
correction(14, 8, [17], 'ctime 검색을 최근 수정되거나 새로 생성된 파일 찾기로 설명한다.', 'ctime은 inode 상태 변경 시각이며 내용 쓰기·소유자·권한 변경에도 갱신될 수 있다. 생성은 지원되는 btime 등과 구분한다. 최근 ctime만으로 새 파일 생성을 확정하지 않는다.', 'ctime=생성 시각 주장은 오답이다. 내용 수정·상태 변경·생성을 구분한다.', 'verified', ['inode']);
correction(14, 9, [17, 18], '패스워드 파일·UID 0·외부/국외 접속 확인이 계정 정보 종류와 침해 확정 조건을 혼동하게 할 수 있다.', 'passwd와 제한된 shadow의 역할을 구분한다. UID 0·root 로그인·국외 IP는 권한·위치 단서이며 무단 접근 여부는 승인·인증·행위 증거를 대조한다. 셸 기록은 완전한 감사 기록이 아니다.', 'passwd의 x를 비밀번호 없음으로, 모든 root·국외 접속을 침해로 채점하지 않는다.', 'verified', ['passwd', 'shadow', 'forensic']);
correction(14, 10, [9, 17, 18], '과거 known goods·악성 파일 fingerprint 사이트와 NSRL이 무결성 검사 항목으로 나열된다.', 'NSRL은 알려진 출처의 소프트웨어 식별 자료이며 일부는 공격 도구 등으로 간주될 수도 있어 등재가 무해함을 보장하지 않는다. 신뢰 가능한 동일 버전과 비교하고 미등재를 악성 증명으로, 파일 하나의 일치를 호스트 전체 정상 증명으로 쓰지 않는다. 과거 사이트의 현재 안전성·가용성은 보장하지 않는다.', '과거 사이트 방문·도구 다운로드를 요구하지 않고 해시·기준선·범위 한계를 평가한다.', 'contextualized', ['nsrl', 'forensic']);
correction(14, 11, [15, 16], '구형 MetaEdit 및 웹쉘 패턴 검색으로 공격자 IP와 웹쉘을 확인한다고 설명한다.', '패턴 일치는 조사 후보이며 실행·주체·실제 피해와 구분한다. 미일치는 부재 증거가 아니다. 가상 디렉토리·권한·로그 설정·변경 이력과 교차 확인한다.', '공격 패턴 실행을 재현하지 않고 검색의 오탐·누락과 보완 증거를 평가한다.', 'contextualized', ['forensic', 'log', 'ir']);
